const text = key => String($json[key] || '').trim();
const council = text('council').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const batch = text('batch');
const input_directory = text('input_directory').replace(/\/+$/, '');
if (!council) throw new Error('Council is required.');
if (!batch) throw new Error('A registered batch is required.');
if (!input_directory.startsWith('/data/') || input_directory.includes('/../') || input_directory.startsWith('/data/file-browser-data')) throw new Error('Input directory must be a safe path below /data and outside /data/file-browser-data.');
return [{json:{council,batch,input_directory,source_path:text('source_path'),capture_rules_paths:text('capture_rules_paths'),s3_inventory_paths:text('s3_inventory_paths'),portal_evidence_paths:text('portal_evidence_paths')}}];

const result = $json;
if (!result.coverage?.exact) throw new Error('Mapping completed without exact source/mapping/audit coverage.');
return [{json:{status:result.status,production_published:false,job_id:result.job_id,council:result.council,batch:result.batch,case_count:result.case_count,match_status_counts:result.match_status_counts,source_type_counts:result.source_type_counts,selected_capture_rules:result.selected_capture_rules,selected_s3_inventory:result.selected_s3_inventory,selected_portal_evidence:result.selected_portal_evidence,outputs:result.outputs}}];
